const productUrl=(key,id)=>`/${key}/products/${id}/`;
const compareUrl=(key,slug)=>`/${key}/compare/${slug}/`;
const pairKey=(a,b)=>[a,b].sort().join('::');
const scoreDistance=(a,b)=>Object.keys(a.scores).reduce((s,k)=>s+Math.abs((a.scores[k]||0)-(b.scores[k]||0)),0)+(a.brand===b.brand?-5:0);
const selectPairs=(cat)=>{
  const map=new Map(cat.products.map(p=>[p.id,p]));const out=[],used=new Set(),appear=new Map();
  const add=(aId,bId)=>{const a=map.get(aId),b=map.get(bId);if(!a||!b)return;const k=pairKey(a.id,b.id);if(used.has(k))return;used.add(k);out.push([a,b,`${a.id}-vs-${b.id}`]);appear.set(a.id,(appear.get(a.id)||0)+1);appear.set(b.id,(appear.get(b.id)||0)+1)};
  cat.seeds.forEach(([a,b])=>add(a,b));
  const candidates=[];for(let i=0;i<cat.products.length;i++)for(let j=i+1;j<cat.products.length;j++){const a=cat.products[i],b=cat.products[j];if(!used.has(pairKey(a.id,b.id)))candidates.push([a,b,scoreDistance(a,b)])}
  candidates.sort((x,y)=>x[2]-y[2]);for(const [a,b] of candidates){if(out.length>=12)break;if((appear.get(a.id)||0)>=2||(appear.get(b.id)||0)>=2)continue;add(a.id,b.id)}
  for(const [a,b] of candidates){if(out.length>=12)break;add(a.id,b.id)}
  return out.slice(0,12);
};
