const compareHtml=(key,cat,a,b,slug)=>`<!doctype html><html lang="ja"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(a.name)}と${esc(b.name)}を比較 2026｜みんなの比較表</title><meta name="description" content="${esc(a.name)}と${esc(b.name)}を主要仕様で横並び比較。"><meta name="robots" content="index,follow,max-image-preview:large"><link rel="canonical" href="${ORIGIN}${compareUrl(key,slug)}"><link rel="icon" href="/favicon.svg"><link rel="stylesheet" href="/guides.css"><link rel="stylesheet" href="/site-ui.css"></head><body><header class="guide-header"><div class="guide-header-inner"><a class="guide-logo" href="/"><span>✓</span><span>みんなの比較表</span></a><nav class="guide-nav"><a href="/${key}/">${cat.label}比較</a><a href="/${key}/compare/">直接比較一覧</a></nav></div></header><main class="guide-main"><div class="breadcrumbs"><a href="/">トップ</a> › <a href="/${key}/">${cat.label}</a> › 2製品比較</div><span class="update-pill">2026年10月更新</span><h1>${esc(a.name)}<br>vs ${esc(b.name)}</h1><p class="lead">主要仕様を同じ表で確認し、どの違いを重視するか整理できます。</p><div class="table-scroll"><table class="spec-table"><thead><tr><th>比較項目</th><th>${esc(a.name)}</th><th>${esc(b.name)}</th></tr></thead><tbody>${cat.rows.map(([l,k])=>`<tr><td>${l}</td><td>${esc(a.facts[k]||'公式で確認')}</td><td>${esc(b.facts[k]||'公式で確認')}</td></tr>`).join('')}</tbody></table></div><div class="related"><a href="${productUrl(key,a.id)}">${esc(a.name)}の詳細</a><a href="${productUrl(key,b.id)}">${esc(b.name)}の詳細</a><a href="/${key}/">20${cat.item}を比較</a></div></main><footer class="guide-footer"><div class="guide-footer-inner"><a href="/">みんなの比較表</a></div></footer><script src="/market-links.js" defer></script></body></html>`;
const hubHtml=(key,cat,pairs)=>`<!doctype html><html lang="ja"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${cat.label}の2製品比較12組 2026｜みんなの比較表</title><meta name="description" content="${cat.label}の代表的な12組を直接比較。"><meta name="robots" content="index,follow,max-image-preview:large"><link rel="canonical" href="${ORIGIN}/${key}/compare/"><link rel="icon" href="/favicon.svg"><link rel="stylesheet" href="/guides.css"><link rel="stylesheet" href="/site-ui.css"></head><body><header class="guide-header"><div class="guide-header-inner"><a class="guide-logo" href="/"><span>✓</span><span>みんなの比較表</span></a></div></header><main class="guide-main"><div class="breadcrumbs"><a href="/">トップ</a> › <a href="/${key}/">${cat.label}</a> › 直接比較一覧</div><span class="update-pill">2026年10月更新</span><h1>${cat.label}<br>2製品比較12組</h1><p class="lead">候補を2つまで絞ったときに、主要仕様を横並びで確認できます。</p><div class="discovery-grid">${pairs.map(([a,b,s])=>`<a class="discovery-card" href="${compareUrl(key,s)}"><b>${esc(a.name)} vs ${esc(b.name)}</b><small>主要仕様を直接比較 →</small></a>`).join('')}</div><div class="cta"><h2>20${cat.item}から探し直す</h2><a href="/${key}/">${cat.label}比較へ →</a></div></main><footer class="guide-footer"><div class="guide-footer-inner"><a href="/">みんなの比較表</a></div></footer><script src="/market-links.js" defer></script></body></html>`;

const mergeSitemap=(file,urls,priority='0.7')=>{
  let current=[];if(fs.existsSync(file)){const xml=fs.readFileSync(file,'utf8');current=[...xml.matchAll(/<loc>([^<]+)<\/loc>/g)].map(m=>m[1])}
  const all=[...new Set([...current,...urls])];
  write(file,`<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${all.map(u=>`  <url><loc>${u}</loc><lastmod>${TODAY}</lastmod><changefreq>weekly</changefreq><priority>${priority}</priority></url>`).join('\n')}\n</urlset>\n`);
};

const productUrls=[],comparisonUrls=[],categoryUrls=[],guideUrls=[];
for(const [key,cat] of Object.entries(cats)){
  write(path.join(publicDir,key,'index.html'),categoryHtml(key,cat));
  categoryUrls.push(`${ORIGIN}/${key}/`);
  for(const [slug,label,desc] of cat.guides){write(path.join(publicDir,key,slug,'index.html'),guideHtml(key,cat,slug,label,desc));guideUrls.push(`${ORIGIN}/${key}/${slug}/`)}
  for(const p of cat.products){write(path.join(publicDir,key,'products',p.id,'index.html'),productHtml(key,cat,p));productUrls.push(ORIGIN+productUrl(key,p.id))}
  const pairs=selectPairs(cat);
  for(const [a,b,slug] of pairs){write(path.join(publicDir,key,'compare',slug,'index.html'),compareHtml(key,cat,a,b,slug));comparisonUrls.push(ORIGIN+compareUrl(key,slug))}
  write(path.join(publicDir,key,'compare','index.html'),hubHtml(key,cat,pairs));comparisonUrls.push(`${ORIGIN}/${key}/compare/`);
}
mergeSitemap(path.join(publicDir,'sitemap-products.xml'),productUrls,'0.7');
mergeSitemap(path.join(publicDir,'sitemap-comparisons.xml'),comparisonUrls,'0.72');
mergeSitemap(path.join(publicDir,'sitemap-categories.xml'),categoryUrls,'0.9');
mergeSitemap(path.join(publicDir,'sitemap-guides.xml'),guideUrls,'0.8');

